<?php
/** Slice 3 — on hand, movements, value and the cost walls (ledger.md "Proof": Levels and movements, Walls). Runs FIRST on the fresh database (the empty state). */
require __DIR__ . '/lib.php';
$w = ledger_world();
$bea = person(28); $dana = person(30); $ann = person(29); $marco = person(27); $marcoA = person(27, AIRPORT);

$own = person(1, AIRPORT); $lee = person(31, AIRPORT);
echo "1. An empty site (Airport — the receipts proof stays at Downtown)\n";
$fresh = (int) one('SELECT count(*) FROM inventory_balances b JOIN storage_areas a ON a.id = b.storage_area_id WHERE a.scope_id = :s AND b.qty_base <> 0', ['s' => AIRPORT]) === 0;
$h = page($own, '/stock/')['body'];
ok($fresh && str_contains($h, 'id="stock-levels-empty"') && str_contains($h, 'Nothing on hand at this site yet'), 'an empty site: the empty state in words');
ok(str_contains($h, 'id="stock-levels-receive-btn"') && str_contains($h, 'id="stock-levels-waste-btn"') && str_contains($h, 'id="stock-levels-produce-btn"'), '…with the three big buttons (receive, waste, a prep batch)');
$h = page($lee, '/stock/')['body'];
ok(str_contains($h, 'id="stock-levels-empty"') && !str_contains($h, 'id="stock-levels-big-buttons"'), 'a Viewer gets the empty state and no big buttons');
ok(str_contains(page($own, '/stock/movements')['body'], 'id="stock-movements-empty"'), 'no movements yet');
$h = page($own, '/stock/value')['body'];
ok(str_contains($h, 'id="stock-value-empty"') || str_contains($h, 'id="stock-value-total"'), 'the value screen answers on an empty site');

echo "2. On hand after receipts\n";
$gA = stock_in($own, $w['awalkin'], [['ingredient' => 'L-FLOUR', 'qty' => 4, 'unit' => 'bag50', 'unit_cost' => 25], ['ingredient' => 'L-EGG', 'qty' => 2, 'unit' => 'case', 'unit_cost' => 54]], $w['sysco']);
stock_in($own, $w['abar'], [['ingredient' => 'L-GIN', 'qty' => 1, 'unit' => 'case6', 'unit_cost' => 108], ['ingredient' => 'L-LIME', 'qty' => 1, 'unit' => 'case', 'unit_cost' => 38]]);
$h = page($own, '/stock/')['body'];
ok(str_contains($h, 'id="levels-table"') && str_contains($h, 'id="level-row-' . $w['flour'] . '-' . $w['awalkin'] . '"'), 'stock-levels lists flour in the walk-in');
preg_match('/id="level-row-' . $w['flour'] . '-' . $w['awalkin'] . '">(.*?)<\/tr>/s', $h, $m); $row = $m[1] ?? '';
ok(str_contains($row, '4 bag50') && str_contains($row, '(90,718.474 g)'), 'flour as "4 bag50 (90 718 g)" — the count unit, the base muted');
preg_match('/id="level-row-' . $w['egg'] . '-' . $w['awalkin'] . '">(.*?)<\/tr>/s', $h, $m); $row = $m[1] ?? '';
ok(str_contains($row, '12 flat'), 'eggs as "12 flat"');
ok(str_contains($row, '$108.00'), "the egg row's value to the owner ($108.00)");
preg_match('/id="levels-total-value">([^<]+)</', $h, $m);
ok(trim($m[1] ?? '') === '$' . number_format((float) one('SELECT sum(on_hand_value) FROM ingredient_site_costs WHERE scope_id = :s', ['s' => AIRPORT]), 2), "the site total = Σ the site's on-hand value");
ok(str_contains($h, 'id="level-row-' . $w['gin'] . '-' . $w['abar'] . '"'), 'one row per ingredient and area (gin in the bar)');
$h = page($own, '/stock/?area=' . $w['abar'])['body'];
ok(str_contains($h, 'id="level-row-' . $w['gin'] . '-' . $w['abar'] . '"') && !str_contains($h, 'id="level-row-' . $w['flour'] . '-'), 'filtered by area: the bar only');
$h = page($own, '/stock/?q=lime')['body'];
ok(str_contains($h, 'id="level-row-' . $w['lime'] . '-') && !str_contains($h, 'id="level-row-' . $w['gin'] . '-'), 'searched by name');
$h = page($own, '/stock/?q=zzzz')['body'];
ok(str_contains($h, 'id="stock-levels-empty"') && str_contains($h, 'Nothing matches'), 'a search that matches nothing says so');
ok(!str_contains(page($own, '/stock/')['body'], 'id="level-below-par-' . $w['flour']), 'no par, no "below par"');
as_member(1);
ri_sql('INSERT INTO ingredient_site_settings (ingredient_id, scope_id, par_base) VALUES (:i, :s, 250000) ON CONFLICT (ingredient_id, scope_id) DO UPDATE SET par_base = 250000', ['i' => $w['flour'], 's' => AIRPORT]);
$h = page($own, '/stock/')['body'];
ok(str_contains($h, 'id="level-below-par-' . $w['flour'] . '-' . $w['awalkin'] . '"'), 'a par of 250 kg marks flour below par');
$h = page($own, '/stock/?below_par=1')['body'];
ok(str_contains($h, 'id="level-row-' . $w['flour'] . '-' . $w['awalkin'] . '"') && !str_contains($h, 'id="level-row-' . $w['egg'] . '-'), 'the below-par filter lists flour alone');
$r = page($own, '/stock/?format=csv');
$lines = array_values(array_filter(explode("\n", trim($r['body']))));
$hdr = str_getcsv($lines[0] ?? '');
ok($r['code'] === 200 && preg_match('/^Content-Type: text\/csv/mi', $r['headers']) === 1, '?format=csv answers text/csv');
ok(count($lines) - 1 === (int) one('SELECT count(*) FROM inventory_balances b JOIN storage_areas a ON a.id = b.storage_area_id WHERE a.scope_id = :s AND b.qty_base <> 0', ['s' => AIRPORT]) && in_array('value', $hdr, true), '…with the same rows as the screen, and a value column for a cost-seer');
$r = page($lee, '/stock/?format=csv');
ok(!in_array('value', str_getcsv(explode("\n", $r['body'])[0] ?? ''), true), "a Viewer's CSV has no value column");
$h = page($lee, '/stock/')['body'];
preg_match('/id="level-row-' . $w['egg'] . '-' . $w['awalkin'] . '">(.*?)<\/tr>/s', $h, $m);
ok(str_contains($m[1] ?? '', '12 flat') && str_contains($m[1] ?? '', 'title="cost withheld">—') && !str_contains($h, '$108.00'), 'a Viewer sees the quantities and "—" for cost');
$j = get_json($ann, '/stock/');
ok(($j['json']['data']['cost_withheld'] ?? false) === true && !array_key_exists('value', $j['json']['data']['levels'][0] ?? ['value' => 1]), "the levels' JSON for Ann at Downtown: cost_withheld, no value key");

echo "3. Movements of every type\n";
$g1 = stock_in($dana, $w['dry'], [['ingredient' => 'L-FLOUR', 'qty' => 1, 'unit' => 'bag50', 'unit_cost' => 25], ['ingredient' => 'L-EGG', 'qty' => 1, 'unit' => 'case', 'unit_cost' => 54]], $w['sysco']);
stock_in($dana, $w['walkin'], [['ingredient' => 'L-CHK', 'qty' => 1, 'unit' => 'case', 'weight_qty' => 40, 'weight_unit' => 'lb', 'unit_cost' => 3.10], ['ingredient' => 'L-LIME', 'qty' => 1, 'unit' => 'case', 'unit_cost' => 38]], $w['sysco']);
post($marco, '/transfers/save.php', ['from_area' => $w['walkin'], 'to_site' => AIRPORT, 'to_area' => $w['awalkin'], 'ingredient' => 'L-LIME', 'qty' => '20', 'unit' => 'each']);
$t = last_id('inventory_transfers'); post($marco, '/transfers/send.php', ['transfer' => $t]); post($marco, '/transfers/receive.php', ['transfer' => $t]);
post($dana, '/adjustments/save.php', ['area' => $w['walkin'], 'reason' => 'breakage', 'ingredient' => 'L-EGG', 'qty_delta' => '-2', 'unit' => 'each']);
$a = last_id('inventory_adjustments'); post($dana, '/adjustments/post.php', ['adjustment' => $a]);
post($dana, '/production/save.php', ['recipe' => $w['r_stock'], 'batches' => '1', 'area' => $w['walkin']]);
$b = last_id('production_batches');
post($dana, '/waste/save.php', ['stage' => 'ingredient', 'ingredient' => 'L-LIME', 'qty' => '4', 'unit' => 'each', 'reason' => 'spoilage', 'area' => $w['walkin']]);
$wl = last_id('waste_logs');
$tid = (int) one("SELECT id FROM inventory_transactions WHERE reference_kind = 'goods_receipt' AND reference_id = :g AND ingredient_id = :e", ['g' => $g1, 'e' => $w['egg']]);
post($dana, '/stock/reverse.php', ['transaction' => $tid]);
$types = array_column(q("SELECT DISTINCT txn_type FROM inventory_transactions WHERE scope_id = 101"), 'txn_type');
$h = page($dana, '/stock/movements')['body'];
$chips = ['receipt' => 'success', 'transfer_out' => 'info', 'adjustment' => 'secondary', 'production_out' => 'warning', 'production_in' => 'warning', 'waste' => 'danger', 'reversal' => 'dark'];
$all = true;
foreach ($chips as $k => $c) { $all = $all && in_array($k, $types, true) && str_contains($h, '<span class="badge bg-soft-' . $c . ' text-' . $c . '">' . ['receipt' => 'receipt', 'transfer_out' => 'transfer out', 'adjustment' => 'adjustment', 'production_out' => 'used in prep', 'production_in' => 'made', 'waste' => 'waste', 'reversal' => 'reversal'][$k] . '</span>'); }
ok($all, 'the movements table shows every type chip (receipt, transfer out, adjustment, used in prep, made, waste, reversal)');
$hA = page($marcoA, '/stock/movements')['body'];
ok(str_contains($hA, '>transfer in</span>'), "…and the transfer in at Airport's movements");
$num = (string) one('SELECT number FROM goods_receipts WHERE id = :g', ['g' => $g1]);
preg_match('/id="movement-row-' . $tid . '">(.*?)<\/tr>/s', $h, $m); $row = $m[1] ?? '';
ok(str_contains($row, 'href="/receipts/' . $g1 . '"') && str_contains($row, '>' . $num . '<'), "a receipt's movement links its document by number");
ok(str_contains($row, 'SMOKE Sysco'), '…and names the counterparty (the supplier)');
ok(str_contains($h, 'href="/transfers/' . $t . '"') && str_contains($h, 'href="/adjustments/' . $a . '"') && str_contains($h, 'href="/production/' . $b . '"') && str_contains($h, 'href="/waste/' . $wl . '"'), 'every document links: the transfer, the adjustment, the batch, the waste log');
$h = page($dana, '/stock/movements?type=waste')['body'];
ok(str_contains($h, '>waste</span>') && !str_contains($h, '>receipt</span>'), 'filtered by type');
$h = page($dana, '/stock/movements?ingredient=' . $w['gin'])['body'];
ok(substr_count($h, 'id="movement-row-') === (int) one('SELECT count(*) FROM inventory_transactions WHERE scope_id = 101 AND ingredient_id = :i', ['i' => $w['gin']]) && !str_contains($h, 'SMOKE Flour'), 'filtered by ingredient: the gin rows alone');
$h = page($ann, '/stock/movements')['body'];
ok(str_contains($h, 'id="movements-table"') && !str_contains($h, '$0.00') && !preg_match('/\$0\.[0-9]{6}/', $h) && str_contains($h, 'title="cost withheld">—'), 'a Viewer sees the movements, "—" for cost');
ok(!str_contains($h, 'id="movement-reverse-'), '…and no Reverse');
ok(str_contains(page($dana, '/stock/movements')['body'], 'id="movement-reverse-'), 'Dana (counts.approve) has Reverse');

echo "4. Value\n";
$h = page($ann, '/stock/value')['body'];
ok(str_contains($h, 'id="stock-value-withheld"') && !str_contains($h, 'id="stock-value-total"'), 'stock-value says withheld to Ann');
$j = get_json($ann, '/stock/value');
ok($j['code'] === 200 && ($j['json']['data']['cost_withheld'] ?? false) === true && !isset($j['json']['data']['total']), '…and so does its JSON');
$h = page($dana, '/stock/value')['body'];
preg_match('/id="stock-value-total">([^<]+)</', $h, $m);
ok(trim($m[1] ?? '') === '$' . number_format((float) one('SELECT sum(on_hand_value) FROM ingredient_site_costs WHERE scope_id = 101'), 2), 'the total to Dana = Σ on-hand value');
ok(str_contains($h, 'id="value-row-') && str_contains($h, 'id="value-ingredient-row-' . $w['flour'] . '"'), 'by category and by ingredient');
$h = page($dana, '/stock/value?as_of=' . date('Y-m-d', strtotime('-60 days')))['body'];
ok(str_contains($h, 'id="stock-value-empty"') || str_contains($h, '$0.00'), 'as of two months ago: nothing');

echo "5. The walls in the mcp_* views\n";
$cost = static function (int $member, string $sql, array $a = []): array { as_member($member); return array_column(q($sql, $a), 'c'); };
$tx = "SELECT unit_cost_per_base AS c FROM mcp_inventory_transactions WHERE scope_id = :s AND txn_type = 'receipt'";
$allNull = static fn (array $v): bool => $v !== [] && count(array_filter($v, static fn ($x) => $x !== null)) === 0;
$noneNull = static fn (array $v): bool => $v !== [] && count(array_filter($v, static fn ($x) => $x === null)) === 0;
ok($allNull($cost(29, $tx, ['s' => 101])) && $allNull($cost(28, $tx, ['s' => 101])), 'mcp_inventory_transactions: unit cost NULL for Ann and Bea at Downtown');
ok($noneNull($cost(30, $tx, ['s' => 101])) && $noneNull($cost(27, $tx, ['s' => 101])), '…present for Dana and Marco at Downtown');
$txA = "SELECT unit_cost_per_base AS c FROM mcp_inventory_transactions WHERE scope_id = :s AND txn_type = 'transfer_in'";
ok($allNull($cost(27, $txA, ['s' => AIRPORT])), '…NULL for Marco at Airport (Kitchen there)');
$lines = 'SELECT v.cost_per_base AS c FROM mcp_goods_receipt_lines v JOIN goods_receipt_lines l ON l.id = v.goods_receipt_line_id WHERE v.scope_id = 101 AND l.cost_per_base IS NOT NULL';
ok($allNull($cost(28, $lines)) && $noneNull($cost(30, $lines)), 'mcp_goods_receipt_lines: every priced line\'s cost walled for Bea, present for Dana');
ok($allNull($cost(29, 'SELECT avg_cost_per_base AS c FROM mcp_ingredient_site_costs WHERE scope_id = 101')) && $noneNull($cost(27, 'SELECT avg_cost_per_base AS c FROM mcp_ingredient_site_costs WHERE scope_id = 101 AND on_hand_base > 0')), 'mcp_ingredient_site_costs: the average walled for Ann, present for Marco');
ok($allNull($cost(28, 'SELECT cost_total AS c FROM mcp_production_batches')) && $noneNull($cost(30, 'SELECT cost_total AS c FROM mcp_production_batches')), 'mcp_production_batches: cost_total walled for Bea');
ok($allNull($cost(29, 'SELECT cost AS c FROM mcp_waste_logs')) && $noneNull($cost(30, 'SELECT cost AS c FROM mcp_waste_logs')), 'mcp_waste_logs: cost walled for Ann');
ok($cost(28, 'SELECT new_per_base AS c FROM mcp_price_history') === [] && $cost(30, 'SELECT new_per_base AS c FROM mcp_price_history') !== [], 'mcp_price_history: no rows for Bea, rows for Dana');

echo "6. kitchen_sees_cost\n";
as_member(1);
ri_sql('UPDATE site_settings SET kitchen_sees_cost = true WHERE scope_id = 101');
ok($noneNull($cost(28, $tx, ['s' => 101])), 'with kitchen_sees_cost on, the cost is present for Bea in mcp_*');
$bea2 = person(28);
post($bea2, '/receipts/save.php', ['area' => $w['dry'], 'supplier' => $w['sysco']]);
$g = last_id('goods_receipts');
ok(str_contains(page($bea2, '/receipts/' . $g)['body'], 'id="receipt-line-form-field-unit_cost"'), 'Bea sees the cost field on the receipt form');
ok(str_contains(page($bea2, '/receipts/' . $g1)['body'], '$25.00'), "…and the cost on a posted receipt's view");
ok(str_contains(page($bea2, '/stock/value')['body'], 'id="stock-value-total"'), '…and the stock value');
post($bea2, '/receipts/cancel.php', ['receipt' => $g]);
as_member(1);
ri_sql('UPDATE site_settings SET kitchen_sees_cost = false WHERE scope_id = 101');
ok(str_contains(page(person(28), '/stock/value')['body'], 'id="stock-value-withheld"'), 'switched off again: withheld');
finish();
